    38→import org.apache.druid.query.aggregation.AggregatorFactory;
    39→import org.apache.druid.segment.indexing.granularity.GranularitySpec;
    40→import org.apache.druid.segment.indexing.granularity.UniformGranularitySpec;
    41→import org.apache.druid.segment.transform.TransformSpec;
    42→
    43→import javax.annotation.Nullable;
    44→import java.util.Arrays;
    45→import java.util.HashSet;
    46→import java.util.Map;
    47→import java.util.Set;
    48→import java.util.regex.Pattern;
    49→import java.util.stream.Collectors;
    50→
    51→
    52→/**
    53→ *
    54→ */
    55→public class DataSchema
    56→{
    57→  private static final Logger log = new Logger(DataSchema.class);
    58→  private static final Pattern INVALIDCHARS = Pattern.compile("(?s).*[^\\S ].*");
    59→  private final String dataSource;
    60→  private final AggregatorFactory[] aggregators;
    61→  private final GranularitySpec granularitySpec;
    62→  private final TransformSpec transformSpec;
    63→  private final Map<String, Object> parserMap;
    64→  private final ObjectMapper objectMapper;
    65→
    66→  // The below fields can be initialized lazily from parser for backward compatibility.
    67→  private TimestampSpec timestampSpec;
    68→  private DimensionsSpec dimensionsSpec;
    69→
    70→  // This is used for backward compatibility
    71→  private InputRowParser inputRowParser;
    72→
    73→  @JsonCreator
    74→  public DataSchema(
    75→      @JsonProperty("dataSource") String dataSource,
    76→      @JsonProperty("timestampSpec") @Nullable TimestampSpec timestampSpec, // can be null in old task spec
    77→      @JsonProperty("dimensionsSpec") @Nullable DimensionsSpec dimensionsSpec, // can be null in old task spec
    78→      @JsonProperty("metricsSpec") AggregatorFactory[] aggregators,
    79→      @JsonProperty("granularitySpec") GranularitySpec granularitySpec,
    80→      @JsonProperty("transformSpec") TransformSpec transformSpec,
    81→      @Deprecated @JsonProperty("parser") @Nullable Map<String, Object> parserMap,
    82→      @JacksonInject ObjectMapper objectMapper
    83→  )
    84→  {
    85→    validateDatasourceName(dataSource);
    86→    this.dataSource = dataSource;
    87→
    88→    this.timestampSpec = timestampSpec;
    89→    this.aggregators = aggregators == null ? new AggregatorFactory[]{} : aggregators;
    90→    this.dimensionsSpec = dimensionsSpec == null
    91→                          ? null
    92→                          : computeDimensionsSpec(
    93→                              Preconditions.checkNotNull(timestampSpec, "timestampSpec"),
    94→                              dimensionsSpec,
    95→                              this.aggregators
    96→                          );
    97→
    98→    if (granularitySpec == null) {
    99→      log.warn("No granularitySpec has been specified. Using UniformGranularitySpec as default.");
   100→      this.granularitySpec = new UniformGranularitySpec(null, null, null);
   101→    } else {
   102→      this.granularitySpec = granularitySpec;
   103→    }
   104→    this.transformSpec = transformSpec == null ? TransformSpec.NONE : transformSpec;
   105→    this.parserMap = parserMap;
   106→    this.objectMapper = objectMapper;
   107→
   108→    if (aggregators != null && aggregators.length != 0) {
   109→      // validate for no duplication
   110→      Set<String> names = new HashSet<>();
   111→      for (AggregatorFactory factory : aggregators) {
   112→        if (!names.add(factory.getName())) {
   113→          throw new IAE("duplicate aggregators found with name [%s].", factory.getName());
   114→        }
   115→      }
   116→    } else if (this.granularitySpec.isRollup()) {
   117→      log.warn("No metricsSpec has been specified. Are you sure this is what you want?");
   118→    }
   119→  }
   120→
   121→  @VisibleForTesting
   122→  public DataSchema(
   123→      String dataSource,
   124→      TimestampSpec timestampSpec,
   125→      DimensionsSpec dimensionsSpec,
   126→      AggregatorFactory[] aggregators,
   127→      GranularitySpec granularitySpec,
   128→      TransformSpec transformSpec
   129→  )
   130→  {
   131→    this(dataSource, timestampSpec, dimensionsSpec, aggregators, granularitySpec, transformSpec, null, null);
   132→  }
   133→
   134→  // old constructor for backward compatibility
   135→  @Deprecated
   136→  public DataSchema(
   137→      String dataSource,
   138→      Map<String, Object> parserMap,
   139→      AggregatorFactory[] aggregators,
   140→      GranularitySpec granularitySpec,
   141→      TransformSpec transformSpec,
   142→      ObjectMapper objectMapper
   143→  )
   144→  {
   145→    this(dataSource, null, null, aggregators, granularitySpec, transformSpec, parserMap, objectMapper);
   146→  }
   147→
   148→  private static void validateDatasourceName(String dataSource)
   149→  {
   150→    IdUtils.validateId("dataSource", dataSource);
   151→  }
   152→
   153→  private static DimensionsSpec computeDimensionsSpec(
   154→      TimestampSpec timestampSpec,
   155→      DimensionsSpec dimensionsSpec,
   156→      AggregatorFactory[] aggregators
   157→  )
   158→  {
   159→    final Set<String> dimensionExclusions = new HashSet<>();
   160→
   161→    final String timestampColumn = timestampSpec.getTimestampColumn();
   162→    if (!(dimensionsSpec.hasCustomDimensions() && dimensionsSpec.getDimensionNames().contains(timestampColumn))) {
   163→      dimensionExclusions.add(timestampColumn);
   164→    }
   165→
   166→    for (AggregatorFactory aggregator : aggregators) {
   167→      dimensionExclusions.addAll(aggregator.requiredFields());
   168→      dimensionExclusions.add(aggregator.getName());
   169→    }
   170→
   171→    final Set<String> metSet = Arrays.stream(aggregators).map(AggregatorFactory::getName).collect(Collectors.toSet());
   172→    final Set<String> dimSet = new HashSet<>(dimensionsSpec.getDimensionNames());
   173→    final Set<String> overlap = Sets.intersection(metSet, dimSet);
   174→    if (!overlap.isEmpty()) {
   175→      throw new IAE(
   176→          "Cannot have overlapping dimensions and metrics of the same name. Please change the name of the metric. Overlap: %s",
   177→          overlap
   178→      );
   179→    }
   180→
   181→    return dimensionsSpec.withDimensionExclusions(Sets.difference(dimensionExclusions, dimSet));
   182→  }
   183→
   184→  @JsonProperty
   185→  public String getDataSource()
   186→  {
   187→    return dataSource;
   188→  }
   189→
   190→  @Nullable
   191→  @JsonProperty("timestampSpec")
   192→  private TimestampSpec getGivenTimestampSpec()
   193→  {
   194→    return timestampSpec;
   195→  }
   196→
   197→  public TimestampSpec getTimestampSpec()
   198→  {
   199→    if (timestampSpec == null) {
   200→      timestampSpec = Preconditions.checkNotNull(getParser(), "inputRowParser").getParseSpec().getTimestampSpec();
   201→    }
   202→    return timestampSpec;
   203→  }
   204→
   205→  @Nullable
   206→  @JsonProperty("dimensionsSpec")
   207→  private DimensionsSpec getGivenDimensionsSpec()
   208→  {
   209→    return dimensionsSpec;
   210→  }
   211→
   212→  public DimensionsSpec getDimensionsSpec()
   213→  {
   214→    if (dimensionsSpec == null) {
   215→      dimensionsSpec = computeDimensionsSpec(
   216→          getTimestampSpec(),
   217→          Preconditions.checkNotNull(getParser(), "inputRowParser").getParseSpec().getDimensionsSpec(),
   218→          aggregators
   219→      );
   220→    }
   221→    return dimensionsSpec;
   222→  }
   223→
   224→  @JsonProperty("metricsSpec")
   225→  public AggregatorFactory[] getAggregators()
   226→  {
   227→    return aggregators;
   228→  }
   229→
   230→  @JsonProperty
   231→  public GranularitySpec getGranularitySpec()
   232→  {
   233→    return granularitySpec;
   234→  }
   235→
   236→  @JsonProperty
   237→  public TransformSpec getTransformSpec()
   238→  {
   239→    return transformSpec;
   240→  }
   241→
   242→  @Deprecated
   243→  @JsonProperty("parser")
   244→  @Nullable
   245→  @JsonInclude(Include.NON_NULL)
   246→  public Map<String, Object> getParserMap()
   247→  {
   248→    return parserMap;
   249→  }
   250→
   251→  @Nullable
   252→  public InputRowParser getParser()
   253→  {
   254→    if (inputRowParser == null) {
   255→      if (parserMap == null) {
   256→        return null;
   257→      }
   258→      //noinspection unchecked
   259→      inputRowParser = transformSpec.decorate(objectMapper.convertValue(this.parserMap, InputRowParser.class));
   260→      ParseSpec parseSpec = inputRowParser.getParseSpec();
   261→      parseSpec = parseSpec.withDimensionsSpec(
   262→          computeDimensionsSpec(parseSpec.getTimestampSpec(), parseSpec.getDimensionsSpec(), aggregators)
   263→      );
   264→      if (timestampSpec != null) {
   265→        parseSpec = parseSpec.withTimestampSpec(timestampSpec);
   266→      }
   267→      if (dimensionsSpec != null) {
   268→        parseSpec = parseSpec.withDimensionsSpec(dimensionsSpec);
   269→      }
   270→      inputRowParser = inputRowParser.withParseSpec(parseSpec);
   271→    }
   272→    return inputRowParser;
   273→  }
   274→
   275→  public DataSchema withGranularitySpec(GranularitySpec granularitySpec)
   276→  {
   277→    return new DataSchema(
   278→        dataSource,
   279→        timestampSpec,
   280→        dimensionsSpec,
   281→        aggregators,
   282→        granularitySpec,
   283→        transformSpec,
   284→        parserMap,
   285→        objectMapper
   286→    );
   287→  }
   288→
   289→  public DataSchema withTransformSpec(TransformSpec transformSpec)
   290→  {
   291→    return new DataSchema(
   292→        dataSource,
   293→        timestampSpec,
   294→        dimensionsSpec,
   295→        aggregators,
   296→        granularitySpec,
   297→        transformSpec,
   298→        parserMap,
   299→        objectMapper
   300→    );
   301→  }
   302→
   303→  @Override
   304→  public String toString()
   305→  {
   306→    return "DataSchema{" +
   307→           "dataSource='" + dataSource + '\'' +
   308→           ", aggregators=" + Arrays.toString(aggregators) +
   309→           ", granularitySpec=" + granularitySpec +
   310→           ", transformSpec=" + transformSpec +
   311→           ", parserMap=" + parserMap +
   312→           ", timestampSpec=" + timestampSpec +
   313→           ", dimensionsSpec=" + dimensionsSpec +
   314→           ", inputRowParser=" + inputRowParser +
   315→           '}';
   316→  }
   317→}
