    /**
     * Validates that a JavaScript function doesn't contain dangerous patterns that could be used
     * for arbitrary code execution. This prevents access to Java classes that could be exploited.
     */
    private static void validateJavaScriptScript(String script)
    {
      if (script == null) {
        return;
      }

      // Normalize the script for checking (remove comments, whitespace variations)
      String normalizedScript = script.toLowerCase().replaceAll("\\s+", " ").trim();

      // List of dangerous patterns that indicate potential code execution
      // This includes patterns that would allow access to Java classes and methods
      String[] dangerousPatterns = {
        "java.lang.runtime",
        "java.lang.system",
        "java.io.file",
        "java.io.filereader",
        "java.io.filewriter",
        "java.net.socket",
        "java.net.url",
        "java.net.httpurlconnection",
        "java.net.mailto",
        "java.nio.file.files",
        "java.nio.file.path",
        "java.class",
        "java.class.forname",
        "packages.",
        "javascript",
        "getclass()",
        "getclass().forname",
        "exec(",
        "eval(",
        "load(",
        "loadfunction("
      };

      for (String pattern : dangerousPatterns) {
        if (normalizedScript.contains(pattern)) {
          throw new ISE(
              "JavaScript function contains disallowed pattern: %s. " +
              "JavaScript filters do not allow access to Java classes or dangerous methods for security reasons.",
              pattern
          );
        }
      }

      // Additional check for nested function definitions that might be used to bypass filters
      if (normalizedScript.contains("function(") && normalizedScript.contains("{")) {
        // Count braces to detect complex nested structures
        int braceCount = 0;
        for (char c : normalizedScript.toCharArray()) {
          if (c == '{') {
            braceCount++;
          } else if (c == '}') {
            braceCount--;
            if (braceCount < 0) {
              break;
            }
          }
        }
        // If there are deeply nested structures, it might be an attempt to obfuscate dangerous code
        if (braceCount > 5) {
          throw new ISE(
              "JavaScript function appears to be overly complex. " +
              "Simple filter functions should not require deep nesting."
          );
        }
      }
    }
  }
}

