  {
    return ImmutableSet.of(dimension);
  }

  @Override
  public boolean equals(Object o)
  {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }
    JavaScriptDimFilter that = (JavaScriptDimFilter) o;
    return dimension.equals(that.dimension) &&
           function.equals(that.function) &&
           Objects.equals(extractionFn, that.extractionFn) &&
           Objects.equals(filterTuning, that.filterTuning);
  }

  @Override
  public int hashCode()
  {
    return Objects.hash(dimension, function, extractionFn, filterTuning);
  }

  @Override
  public String toString()
  {
    return "JavaScriptDimFilter{" +
           "dimension='" + dimension + '\'' +
           ", function='" + function + '\'' +
           ", extractionFn=" + extractionFn +
           ", filterTuning=" + filterTuning +
           '}';
  }

  public static class JavaScriptPredicateFactory implements DruidPredicateFactory
  {
    final ScriptableObject scope;
    final Function fnApply;
    final String script;
    final ExtractionFn extractionFn;

    public JavaScriptPredicateFactory(final String script, final ExtractionFn extractionFn)
    {
      Preconditions.checkNotNull(script, "script must not be null");
      // Validate that the script doesn't contain dangerous patterns
      validateJavaScriptScript(script);
      this.script = script;
      this.extractionFn = extractionFn;

      final Context cx = Context.enter();
      try {
        cx.setOptimizationLevel(9);
        scope = cx.initStandardObjects();

        fnApply = cx.compileFunction(scope, script, "script", 1, null);
      }
      finally {
        Context.exit();
      }
    }

    @Override
    public Predicate<String> makeStringPredicate()
    {
      return input -> applyObject(input);
    }

    @Override
    public DruidLongPredicate makeLongPredicate()
    {
      // Can't avoid boxing here because the Mozilla JS Function.call() only accepts Object[]
      return new DruidLongPredicate()
      {
        @Override
        public boolean applyLong(long input)
        {
          return JavaScriptPredicateFactory.this.applyObject(input);
        }

        @Override
        public boolean applyNull()
        {
          return JavaScriptPredicateFactory.this.applyObject(null);
        }
      };
    }

    @Override
    public DruidFloatPredicate makeFloatPredicate()
    {
      // Can't avoid boxing here because the Mozilla JS Function.call() only accepts Object[]
      return new DruidFloatPredicate()
      {
        @Override
        public boolean applyFloat(float input)
        {
          return JavaScriptPredicateFactory.this.applyObject(input);
        }

        @Override
        public boolean applyNull()
        {
          return JavaScriptPredicateFactory.this.applyObject(null);
        }
      };
    }

    @Override
    public DruidDoublePredicate makeDoublePredicate()
    {
      // Can't avoid boxing here because the Mozilla JS Function.call() only accepts Object[]
      return new DruidDoublePredicate()
      {
        @Override
        public boolean applyDouble(double input)
        {
          return JavaScriptPredicateFactory.this.applyObject(input);
        }

        @Override
        public boolean applyNull()
        {
          return JavaScriptPredicateFactory.this.applyObject(null);
        }
      };
    }

    public boolean applyObject(final Object input)
    {
      // one and only one context per thread
      final Context cx = Context.enter();
      try {
        return applyInContext(cx, input);
      }
      finally {
        Context.exit();
      }
    }

    public boolean applyInContext(Context cx, Object input)
    {
      if (extractionFn != null) {
        input = extractionFn.apply(input);
      }
      return Context.toBoolean(fnApply.call(cx, scope, scope, new Object[]{input}));
    }

    @Override
    public boolean equals(Object o)
    {
      if (this == o) {
        return true;
      }
      if (o == null || getClass() != o.getClass()) {
        return false;
      }

      JavaScriptPredicateFactory that = (JavaScriptPredicateFactory) o;

      if (!script.equals(that.script)) {
        return false;
      }

      return true;
    }

    @Override
    public int hashCode()
    {
      return script.hashCode();
    }

    /**
     * Validates that a JavaScript function doesn't contain dangerous patterns that could be used
     * for arbitrary code execution. This prevents access to Java classes that could be exploited.
     */
    private static void validateJavaScriptScript(String script)
    {
      if (script == null) {
        return;
      }

      // Normalize the script for checking (remove comments, whitespace variations)
      String normalizedScript = script.toLowerCase().replaceAll("\\s+", " ").trim();

      // List of dangerous patterns that indicate potential code execution
      // This includes patterns that would allow access to Java classes and methods
      String[] dangerousPatterns = {
        "java.lang.runtime",
        "java.lang.system",
        "java.io.file",
        "java.io.filereader",
        "java.io.filewriter",
        "java.net.socket",
        "java.net.url",
        "java.net.httpurlconnection",
        "java.net.mailto",
        "java.nio.file.files",
        "java.nio.file.path",
        "java.class",
        "java.class.forname",
        "packages.",
        "javascript",
        "getclass()",
        "getclass().forname",
        "exec(",
        "eval(",
        "load(",
        "loadfunction("
      };

      for (String pattern : dangerousPatterns) {
        if (normalizedScript.contains(pattern)) {
          throw new ISE(
              "JavaScript function contains disallowed pattern: %s. " +
              "JavaScript filters do not allow access to Java classes or dangerous methods for security reasons.",
              pattern
          );
        }
      }

      // Additional check for nested function definitions that might be used to bypass filters
      if (normalizedScript.contains("function(") && normalizedScript.contains("{")) {
        // Count braces to detect complex nested structures
        int braceCount = 0;
        for (char c : normalizedScript.toCharArray()) {
          if (c == '{') {
            braceCount++;
          } else if (c == '}') {
            braceCount--;
            if (braceCount < 0) {
              break;
            }
          }
        }
        // If there are deeply nested structures, it might be an attempt to obfuscate dangerous code
        if (braceCount > 5) {
          throw new ISE(
              "JavaScript function appears to be overly complex. " +
              "Simple filter functions should not require deep nesting."
          );
        }
      }
    }
  }
}

